cd /tmp/claude-1000/-home-jess-Documents-primary-juvenile-meta-analysis/8d7d0ec0-0cc8-48c7-88d9-13b79f779dc2/scratchpad; cat > p11.py <<'E'
from lib import *
import re,sys
stem="Kubiak_Cunn_2009"; st="2026-10-09T02:43:39Z"
L=open("/home/jess/Documents/primary_juvenile_meta-analysis/data/papers_test/md_agents/Kubiak_Cunn_2009.md").read().split("\n")
src="kubiak, p. j. (2009). fire responses of bushland plants after the january 1994 wildfires in northern sydney. cunninghamia, 11(1), 131-165."
start=[i for i,l in enumerate(L) if l.startswith("#### **Appendix 1")][0]
page=145; recs=[]
for l in L[start:]:
    m=re.match(r"^(\d{3}) Cunninghamia 11\(1\): 2009 — Kubiak",l) or re.match(r"^Cunninghamia 11\(1\): 2009 — Kubiak.* (\d{3})$",l)
    if m: page=int(m.group(1)); continue
    if l.startswith("| ") and "Family | Species" not in l and "---" not in l:
        c=[x.strip() for x in l.strip().strip("|").split("|")]
        assert len(c)==12; recs.append((page,c))
print(len(recs))

def num(v): 
    s=f"{v:.3f}".rstrip("0").rstrip("."); return s
def parse_time(cell):
    """return (lo,hi,mod,unit,approx) or None"""
    s=cell.replace("<u>","").replace("</u>","").replace("**","").replace("–","-").strip()
    m=re.match(r"At least (\d+) years",s)
    if m: return (m.group(1),None,">","y",False)
    m=re.match(r"Less than (\d+) year",s)
    if m: return (m.group(1),None,"<","y",False)
    m=re.match(r"^(\d+)\s*,\s*(\d+)w",s)
    if m: return (m.group(1),None,"","w",False)
    m=re.match(r"^(\d+) & (\d+)w",s)
    if m: return (m.group(1),None,"","w",False)
    m=re.search(r"(c\.\s*)?\??\s*(\d+(?:\.\d+)?)(?:\s*-\s*(\d+(?:\.\d+)?))?(\+)?\??\s*([wy])\b",s)
    if m: return (m.group(2),m.group(3),">" if m.group(4) else "","y" if m.group(5)=="y" else "w",bool(m.group(1)) or "?" in s)
    return None
def conv(cell,to_years):
    t=parse_time(cell)
    if not t: return None
    lo,hi,mod,u,approx=t
    def cv(x):
        if x is None: return None
        v=float(x)
        if u=="w" and to_years: return num(v/52)
        return x
    val=cv(lo)+("-"+cv(hi) if hi else "")
    if mod: val=mod+val
    conv_note=None
    if u=="w" and to_years: conv_note="converted from "+lo+("-"+hi if hi else "")+" weeks"
    unit="years" if (u=="y" or to_years) else "weeks"
    return val,unit,conv_note
FREE=lambda c: bool(re.match(r"[A-Z][a-z]{2,}",c)) and not c.startswith(("At least","Less than"))

VM_NOTE_P="certainty as stated in the paper: 'probably' = say 80-90% sure of observation, 'possibly' = say 50-70% sure of observation"
DEF={"R":"majority of adult plants resprouted after the fires","K":"majority of adult plants killed by the fires","r":"a small proportion of adult plants resprouted after the fires","k":"a small proportion of adult plants were killed by the fires"}
def code_map(code):
    """return (value, note)"""
    c=code.replace(" ","")
    if c=="": return None
    simple={"R":("resprouter",None),"K":("obligate",None)}
    if c in simple: return simple[c]
    def d(x):
        x=x.replace("?","").replace("p","") if x[:1] in ("p","?") and len(x)>1 and x[1:2] in "RKrk" else x
        return x
    if c in("pK","?K","pR","?R"):
        mp={"pK":("obligate","probably killed by the fires"),"?K":("obligate","possibly killed"),"pR":("resprouter","probably resprouted after the fires"),"?R":("resprouter","possibly resprouted")}
        v,df=mp[c]; return v,f"fire response code printed '{c}' = {df}; {VM_NOTE_P}"
    if c=="K/r": return "O/r",f"fire response code printed '{code.strip()}' = K: {DEF['K']}; r: {DEF['r']}"
    if c=="R/k": return "R/o",f"fire response code printed '{c}' = R: {DEF['R']}; k: {DEF['k']}"
    if c in("K/R","R/K"): return "O/R",f"fire response code printed '{c}' = K: {DEF['K']}; R: {DEF['R']}; read as killed and resprouting in similar proportions"
    if c=="?K/r": return "O/r",f"fire response code printed '{c}' = possibly K/r (K: {DEF['K']}; r: {DEF['r']}); certainty as stated in the paper: 'possibly' = say 50-70% sure of observation"
    if c=="pK/r": return "O/r",f"fire response code printed '{c}' = probably K/r (K: {DEF['K']}; r: {DEF['r']}); certainty as stated in the paper: 'probably' = say 80-90% sure of observation"
    if c=="R/?k": return "R/o",f"fire response code printed '{c}' = R: {DEF['R']}; possibly k ({DEF['k']}); certainty as stated in the paper: 'possibly' = say 50-70% sure of observation"
    if c=="k/r": return "",f"fire response code printed '{c}' = k: {DEF['k']}; r: {DEF['r']}; conflicting codes"
    if c in("k","?k"): return "",f"fire response code printed '{c}' = k: {DEF['k']}; no clear class"+("; certainty as stated in the paper: 'possibly' = say 50-70% sure of observation" if c=="?k" else "")
    if c=="?r": return "",f"fire response code printed '{c}' = possibly r: {DEF['r']}; no clear class; certainty as stated in the paper: 'possibly' = say 50-70% sure of observation"
    if c.startswith("K;r"): return "",f"fire response code printed '{code}' = K: {DEF['K']}; r after a moderate intensity fire (m.i.f), 71 weeks; conflicting codes"
    if c.startswith("R(1)"): return "resprouter",f"fire response code printed 'R(1)m.i.f' with text: one plant resprouted after low to medium intensity fire, the canopy of its host was not 100% scorched; (1) = one plant; m.i.f = moderate intensity fire"
    raise Exception(code)

def name_parts(raw):
    n=raw; notes=[]; exotic=False; unc=False
    if n.startswith("(*?)"): n=n[4:]; unc=True; notes.append(f"name printed as '{raw}' (marker '(*?)' may mean possibly exotic, not defined in the paper)")
    elif n.startswith("*"): n=n[1:]; exotic=True
    orig=n
    n=n.replace("–","-").replace("“","").replace("”","")
    n=re.sub(r"\s*\((s\.lat\.|s\.str\.)\)","",n)
    n=re.sub(r"\s*\(syn\. .*\)","",n)
    sub=""
    m=re.search(r" (subsp\.|var\.|cv\.) (\S+)$",n)
    if m: sub=f"{m.group(1)} {m.group(2)}"; n=n[:m.start()]
    parts=n.split(" ")
    g=parts[0]; sp=" ".join(parts[1:])
    sp=sp.replace("?","")
    if sp.startswith("x ") or sp.startswith("X "): sp=sp[2:]; notes.append(f"hybrid marker 'x' printed before epithet in '{orig}'")
    sp=sp.replace("(hybrid)","hybrid")
    sub=sub.replace("?","")
    if re.search(r"\?|\(s\.|\(syn|“",orig+" ") or "?" in raw: notes.append(f"name printed as '{raw}'")
    sp=sp.lower(); sub=sub.lower()
    return g,sp,sub,exotic,unc,notes

FIRE_S="wildfires of january 1994 (lane cove river fire began 6 january 1994, p. 133; narrabeen lagoon fire began 8 january 1994, p. 134); fire_season_categorical derived from these dates"
PW=("responses recorded after the january 1994 wildfires in the lane cove river (lcr) and narrabeen lagoon (nl) catchments, northern sydney; fire responses are for plants with 100% leaf scorch (p. 137); "
 "key (p. 145): R = majority of adult plants resprouted, K = majority killed, r = a small proportion resprouted, k = a small proportion killed, p = probably, ? = possibly; "
 "first flowering of resprouts and of plants from seed in weeks (w) or years (y), underlined values bridge both columns (unclear whether from seed or resprout), bold values = sizable proportion of population flowering; "
 "unmarked species counted as native (abstract: 576 native and 252 exotic species; exotic species marked with * in appendix 1); "
 f"{FIRE_S}; fire_severity_categorical high: fire severity printed 'very high intensity' for the lane cove river fire (p. 133) and 'apparently high intensity' for both areas (p. 134); "
 "coordinates 33°45'S, 151°05'E from abstract and study area (p. 131, p. 133); no rainfall given")
LCR=dict(location_name="lane cove river",latitude="-33.75",longitude="151.0833")
NL=dict(location_name="narrabeen lagoon",latitude="-33.75",longitude="151.0833")
SH=dict(location_name="lane cove river; narrabeen lagoon")

def timecols(r, notes, row):
    fam,name,peak,lcr,nl,seedl,flR,flS,frR,frS,pjp,sjp=r
    # first flowering
    ul=lambda c: "<u>" in c
    def fl(cell,col):
        if not cell: return
        if cell=="Resprouted, low intensity–flowered 92w after fire.":
            v=conv("92w",True); row[col]=v[0]; notes.append(f"{col} {v[2]}; printed 'resprouted, low intensity-flowered 92w after fire.'"); return
        if FREE(cell): notes.append(f"{col} cell text: '{cell.lower()}'"); return
        raw=cell.replace("<u>","").replace("</u>","").replace("**","")
        if ul(cell): return
        v=conv(cell,True)
        if v is None: notes.append(f"{col} printed '{raw}'"); return
        row[col]=v[0]
        if v[2]: notes.append(f"{col} {v[2]}")
        if raw.lower()!=re.sub(r"\s","",raw).lower() or not re.fullmatch(r"\d+(\.\d+)?[wy]",raw.strip()):
            notes.append(f"{col} printed '{raw}'"+("; bold = sizable proportion of population flowering" if "**" in cell else ""))
    # underlined (bridging) first
    if ul(flR) or ul(flS):
        a=flR.replace("<u>","").replace("</u>","").replace("**",""); b=flS.replace("<u>","").replace("</u>","").replace("**","")
        notes.append(f"first flowering printed '{a}' in both the resprout and seed columns (underlined: unclear whether from seed or resprouts), not filled in either column"+("" if a==b else f"; seed column printed '{b}'"))
    fl(flR,"time_to_first_flower_production_resprout_repr3a")
    fl(flS,"age_at_first_flower_production_from_seed_repr3")
    for lab,cell in (("first fruiting resprouts",frR),("first fruiting from seed",frS)):
        if cell:
            raw=cell.replace("<u>","").replace("</u>","").replace("**","")
            if ul(cell) and ul(frR) and ul(frS) and lab.endswith("seed"): continue
            notes.append((lab.replace("first fruiting","first fruiting (underlined, bridges resprout and seed columns)") if ul(cell) else lab)+f" printed '{raw.lower()}'")
    if seedl: notes.append(f"seedlings first observed printed '{seedl.lower()}'")
    if peak: notes.append(f"post-fire flowering or fruiting peak printed '{peak}' (prob. = probable, poss. = possible, pk = peak, pf = post-fire)")
    if pjp:
        if FREE(pjp) and not pjp.startswith("At least"): notes.append(f"primary_juvenile_period text: '{pjp.lower()}'")
        else:
            v=conv(pjp,True)
            row["primary_juvenile_period"]=v[0]
            if v[2]: notes.append(f"primary_juvenile_period {v[2]}")
            if not re.fullmatch(r"\d+(\.\d+)?[wy]",pjp): notes.append(f"primary_juvenile_period printed '{pjp}' (shd = shedding seed or spores; ri. = ripe fruit; grn. = green fruit)")
    if sjp:
        v=conv(sjp,False)
        row["secondary_juvenile_period"]=v[0]; row["time_unit"]=v[1]
        if not re.fullmatch(r"\d+(\.\d+)?[wy]",sjp): notes.append(f"secondary_juvenile_period printed '{sjp}' (shd = shedding seed or spores; ri. = ripe fruit; grn. = green fruit)")

rows=[]; nsh=0
for page,r in recs:
    fam,name,peak,lcr,nl,seedl,flR,flS,frR,frS,pjp,sjp=r
    g,sp,sub,exotic,unc,nn=name_parts(name)
    base=dict(genus=g,species=sp,subsp=sub,scientific_name=f"{g} {sp}",family=fam.lower(),fire_type="wildfire",fire_season_categorical="summer",fire_severity_categorical="high",source=src,file_name=stem)
    if exotic: base["native_status"]="exotic"
    elif unc: pass
    else: base["native_status"]="native"
    loc=f"appendix 1, p. {page}"
    # site codes
    sites=[]
    for lab,code,meta in (("lcr",lcr,LCR),("nl",nl,NL)):
        if not code: continue
        if FREE(code) and not code.startswith("R(1)"):  # text cell
            continue
        sites.append((lab,code,meta))
    txtnotes=[]
    if FREE(nl) and not nl.startswith("R(1)"): txtnotes.append(f"nl cell text: '{nl.lower()}'")
    if FREE(lcr) and not lcr.startswith("R(1)"): txtnotes.append(f"lcr cell text: '{lcr.lower()}'")
    anytime=any([peak,seedl,flR,flS,frR,frS,pjp,sjp])
    def mk(meta,code=None,sitelab=None,times=False):
        row=dict(base); row.update(meta); notes=[loc]
        if code is not None:
            fr=code_map(code)
            if fr[0]: row["fire_response_categorical_surv1"]=fr[0]
            if fr[1]: notes.append(fr[1])
            if code.startswith("R(1)"): row["fire_severity_categorical"]="low-moderate"; notes.append("fire_severity_categorical: printed 'low to medium intensity fire' for this plant")
        if times: timecols(r,notes,row)
        notes+=txtnotes+nn
        if sitelab: pass
        if code is None: notes.append("values not split by site: shared row for lane cove river and narrabeen lagoon, coordinates left empty")
        row["notes"]="; ".join(notes+[PW])
        return row
    if len(sites)==2:
        for lab,code,meta in sites: rows.append(mk(meta,code,lab,False))
        if anytime:
            sh=mk(SH,None,None,True); sh.pop("fire_type",None); sh.pop("fire_season_categorical",None); sh.pop("fire_severity_categorical",None)
            sh["fire_type"]="wildfire"; sh["fire_season_categorical"]="summer"; sh["fire_severity_categorical"]="high"
            rows.append(sh); nsh+=1
    elif len(sites)==1:
        lab,code,meta=sites[0]; rows.append(mk(meta,code,lab,True))
    else:
        if anytime:
            sh=mk(SH,None,None,True); rows.append(sh); nsh+=1
        else:
            print("NO DATA ROW",name)
print(len(rows),"rows; shared",nsh)
# every row needs a fire response or a time value
for x in rows:
    if not any(x.get(c) for c in ["fire_response_categorical_surv1","primary_juvenile_period","age_at_first_flower_production_from_seed_repr3","secondary_juvenile_period","time_to_first_flower_production_resprout_repr3a"]):
